// === Tab: mySketch ===
let x = 0.01;
let y = 0;
let z = 0;

let a = 10;
let b = 28;
let c = 8 / 3;

ArrayList<PVector> points = new ArrayList<PVector>();

function setup() {
	createCanvas(600, 600, WEBGL);
	colorMode(HSB);
}

function draw() {
	background(0);

	let dt = 0.01;
	let dx = (a * (y - x)) * dt;
	let dy = (x * (b - z) - y) * dt;
	let dz = (x * y - c * z) * dt;
	x += dx;
	y += dy;
	z += dz;

	points.add(new PVector(x, y, z));

	translate(width / 2, height / 2);
	scale(5);
	noFill();

	rotateY(map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0, 10));

	let hu = 0;
	beginShape();
	for (let v of points) {
		stroke(hu, 255, 255);
		vertex(v.x, v.y, v.z);
		// let offset = PVector.random3D();
		// offset.mult(0.1);
		// v.add(offset);

		hu += 0.1;
		if (hu > 255) {
			hu = 0;
		}
	}
	endShape();
}

